import ssymm = require( './index' );


// TESTS //

// The function returns a Float32Array...
{
	const A = new Float32Array( 25 );
	const B = new Float32Array( 25 );
	const C = new Float32Array( 25 );

	ssymm( 'row-major', 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectType Float32Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const A = new Float32Array( 25 );
	const B = new Float32Array( 25 );
	const C = new Float32Array( 25 );

	ssymm( 10, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( true, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( false, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( null, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( undefined, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( [], 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( {}, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
	ssymm( ( A: number ): number => A, 'left', 'lower', 5, 5, 1.0, A, 5, B, 5, 1.0, C, 5 ); // $ExpectError
}

